package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Owned synthetic emulator only. Actual SQLite, Views, profile image and upgrade preservation. */
public final class Beta995NativeTest extends Instrumentation {
    int checks;Throwable failure;GrowthActivity growth;String account;
    void check(boolean yes,String label){checks++;if(!yes)throw new AssertionError(label);}
    void main(Runnable run){runOnMainSync(()->{try{run.run();}catch(Throwable e){failure=e;}});if(failure!=null)throw new AssertionError(failure);}
    static String text(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(text(((ViewGroup)v).getChildAt(i)));return s.toString();}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        Context c=getTargetContext();check(c.getPackageName().equals("dev.bennett.codexmeter.trial")&&Build.MODEL.contains("sdk"),"Owned beta emulator");check(SecureTokenStore.load(c)==null||TrialDemo.active(c),"No real account touched");
        check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName.equals("9.9.5"),"Actual installed candidate");
        TrialDemo.prepare(c);account=SubscriptionStore.accountKey(c);JSONObject old=RpgProgressStore.export(c,account);String settings=c.getSharedPreferences("codex_meter_settings_v1",0).getAll().toString();
        BetaDemo995.prepare(c);JSONObject state=BetaGrowthStore.load(c,account);check(state!=null&&state.getInt("level")>=30,"New real engine demo reaches Lv30");
        check(settings.equals(c.getSharedPreferences("codex_meter_settings_v1",0).getAll().toString()),"Transition preserves original usage preferences/snapshot");
        JSONObject archive=BetaGrowthStore.archive(c,account);check(archive!=null&&archive.optJSONObject("rpg")!=null,"Read-only old growth archive exists");
        check(!BetaGrowthStore.start(c,account),"Repeat update/transition does not reset");long total=state.getLong("total");String days=state.getJSONObject("days").toString(),rewards=state.getJSONObject("rewards").toString(),archiveText=archive.toString();
        UsageApi.refreshAndCache(c);TrialDemo.prepare(c);BetaDemo995.prepare(c);check(BetaGrowthStore.load(c,account).getLong("total")==total,"Demo refresh and repeated entry do not award XP");
        JSONObject backup=BetaGrowthStore.export(c,account);check(!backup.toString().contains("SYNTHETIC_TRIAL")&&!backup.toString().contains("access_token"),"Backup excludes credentials");
        check(BetaGrowthStore.restore(c,account,backup),"Valid backup restore");check(BetaGrowthStore.load(c,account).getLong("total")==total,"Restore no duplicate rewards");
        JSONObject broken=new JSONObject(backup.toString());broken.getJSONObject("state").put("total",total+1);boolean rejected=false;try{BetaGrowthStore.restore(c,account,broken);}catch(Exception expected){rejected=true;}check(rejected&&BetaGrowthStore.load(c,account).getLong("total")==total,"Invalid restore preserves SQLite");
        try(BetaGrowthStore db=new BetaGrowthStore(c)){db.getWritableDatabase().execSQL("CREATE TRIGGER qa_block995 BEFORE UPDATE ON profiles BEGIN SELECT RAISE(ABORT,'QA abort'); END");}
        try{boolean rollback=false;try{BetaGrowthStore.equip(c,account,"");}catch(Exception expected){rollback=true;}check(rollback,"Injected SQLite failure surfaces");check(BetaGrowthStore.load(c,account).getLong("total")==total,"Transaction failure retains XP");}finally{try(BetaGrowthStore db=new BetaGrowthStore(c)){db.getWritableDatabase().execSQL("DROP TRIGGER IF EXISTS qa_block995");}}
        BetaIdentity.save(c,"긴이름한글EnglishUser123456");BetaIdentity.prefs(c).edit().putBoolean("setup_done",true).commit();String name=BetaIdentity.name(c);
        growth=(GrowthActivity)startActivitySync(new Intent(c,GrowthActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1300);waitForIdleSync();
        main(()->{View root=growth.findViewById(android.R.id.content);check(root.findViewWithTag("beta:hero")!=null,"Personalized hero visible");check(text(root).contains(name),"Actual stored name used");check(text(root).contains(BetaCopy.t(growth,"missions")),"Mission section visible");check(!text(root).contains("MXP"),"Consumer experience vocabulary");check(Ui.accent(growth,true)==BetaUi.accent(true),"Primary accent independent of grade");});capture(c,"growth");
        for(int period=1;period<=2;period++){final int p=period;main(()->growth.findViewById(android.R.id.content).findViewWithTag("beta995:period:"+p).performClick());Thread.sleep(600);waitForIdleSync();capture(c,period==1?"weekly":"monthly");}
        BetaCatalogActivity catalog=(BetaCatalogActivity)startActivitySync(new Intent(c,BetaCatalogActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);waitForIdleSync();
        main(()->{check(catalog.body.findViewWithTag("beta995:collectible:rpg3.first_day")!=null,"Owned achievement tile");check(catalog.body.findViewWithTag("beta995:collectible:rpg3.annual_gold_3")!=null,"Distinct locked long-term silhouette");catalog.show("rpg3.first_day");check(catalog.dialog.isShowing(),"Short condition modal opens");catalog.dialog.dismiss();check(!catalog.dialog.isShowing(),"Modal dim/touch layer dismissed");});capture(c,"honors");main(catalog::finish);
        BetaCatalogActivity wardrobe=(BetaCatalogActivity)startActivitySync(new Intent(c,BetaCatalogActivity.class).putExtra("titles",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);waitForIdleSync();
        main(()->{check(text(wardrobe.body).contains(name),"Named title preview");wardrobe.show("rpg3.starter");check(wardrobe.dialog.getButton(android.content.DialogInterface.BUTTON_POSITIVE)!=null,"Owned title equipment action");wardrobe.dialog.dismiss();});capture(c,"titles");main(wardrobe::finish);
        check(BetaGrowthStore.equip(c,account,"rpg3.starter"),"Explicit title equip");check(BetaGrowthStore.equip(c,account,""),"Explicit title remove");BetaIdentity.save(c,"새이름 Alex");check(BetaIdentity.title(c,"rpg3.starter").contains("새이름 Alex"),"Name change changes template, stable ID retained");check(BetaGrowthStore.load(c,account).getJSONObject("titles").has("rpg3.starter"),"Name change keeps unlock");
        MeterSettingsActivity settingsScreen=(MeterSettingsActivity)startActivitySync(new Intent(c,MeterSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1200);waitForIdleSync();main(()->{View root=settingsScreen.findViewById(android.R.id.content);check(text(root).contains(BetaCopy.t(settingsScreen,"my_info")),"Four-group settings hub");View advanced=root.findViewWithTag("beta995:advanced");check(advanced!=null,"Advanced settings entry");});capture(c,"settings");main(settingsScreen::finish);
        BetaProfileActivity profile=(BetaProfileActivity)startActivitySync(new Intent(c,BetaProfileActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(800);waitForIdleSync();main(()->{check(profile.png!=null&&profile.image!=null,"Actual bounded PNG generated");check(profile.save.isEnabled()&&profile.share.isEnabled(),"Save/share require explicit choice");check(profile.image.getHeight()>800,"Long name/title canvas retains space");});capture(c,"profile");main(profile::finish);
        BetaArchiveActivity oldScreen=(BetaArchiveActivity)startActivitySync(new Intent(c,BetaArchiveActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);waitForIdleSync();main(()->check(text(oldScreen.body).contains(BetaCopy.t(oldScreen,"readonly")),"Archive read-only label"));capture(c,"archive");main(oldScreen::finish);
        AuthTokens tokens=SecureTokenStore.load(c);try{SecureTokenStore.save(c,new AuthTokens("SYNTHETIC_QA","SYNTHETIC_QA","",System.currentTimeMillis()+86400000,"beta995-other-account",""));main(()->{growth.load(true);check(growth.findViewById(android.R.id.content).findViewWithTag("beta:hero")==null,"Account change removes old hero immediately");});check(BetaGrowthStore.load(c,account)==null,"Old account storage inaccessible through changed session");check(!BetaGrowthStore.equip(c,account,"rpg3.starter"),"Stale account action refused");}finally{SecureTokenStore.save(c,tokens);main(()->growth.load(true));Thread.sleep(500);waitForIdleSync();}
        JSONObject after=BetaGrowthStore.load(c,account);check(after.getLong("total")==total&&after.getJSONObject("days").toString().equals(days)&&after.getJSONObject("rewards").toString().equals(rewards),"All view/settings/profile operations give no XP or mission progress");check(BetaGrowthStore.archive(c,account).toString().equals(archiveText),"Old archive unchanged by new growth or restore");
        main(growth::finish);result.putString("stream","Beta 9.9.5 native: "+checks+" checks passed; real Views/SQLite/PNG, synthetic account only.\n");finish(-1,result);
    }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));finish(0,result);}}
    void capture(Context c,String name)throws Exception{Thread.sleep(200);waitForIdleSync();java.io.File dir=new java.io.File(c.getExternalFilesDir(null),"beta995-captures");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
}
